#> setup -- the libraries and options the rest of the module runs under.
library(bayesnec)
library(brms)
library(ggplot2)
library(dplyr)
library(tidyr)
options(brms.backend = "cmdstanr")
options(mc.cores = 4)
set.seed(333)
data(nec_data)

# The prior figures below draw the densities `get_priors()` returns, rather than
# idealised curves, so that what is plotted is what a fit would actually use.
# sample_priors() returns a named list of draws with a `b_` prefix per parameter.
prior_draws <- function(priors, set) {
  sample_priors(priors, n_samples = 4000, plot = NA) |>
    data.frame() |>
    tidyr::pivot_longer(dplyr::everything(),
                        names_to = "parameter", values_to = "value") |>
    dplyr::mutate(parameter = sub("^b_", "", parameter), set = set)
}

prior_cols <- c("uninformative" = "#1b6ca8", "regularizing" = "#c1440e")


