#   The available prior sets -------------------------------------------------

#> prior-types
formals(bnec)$prior_type

#> fig-prior-sets -- draws a figure on the page; the page shows the figure and not this code.
f_gauss <- bayesnecformula(y ~ crf(x, model = "nec4param"))
p_unin <- get_priors(f_gauss, data = nec_data, family = gaussian())
p_regl <- get_priors(f_gauss, data = nec_data, family = gaussian(),
                     prior_type = "regularizing")

sets <- bind_rows(prior_draws(p_unin, "uninformative"),
                  prior_draws(p_regl, "regularizing")) |>
  filter(parameter %in% c("top", "bot", "nec")) |>
  mutate(parameter = factor(parameter, c("top", "bot", "nec")))

observed <- data.frame(
  parameter = factor(c("top", "bot", "nec"), c("top", "bot", "nec")),
  lo = c(min(nec_data$y), min(nec_data$y), min(nec_data$x)),
  hi = c(max(nec_data$y), max(nec_data$y), max(nec_data$x)))

ggplot(sets, aes(value, colour = set, fill = set)) +
  geom_rect(data = observed, aes(xmin = lo, xmax = hi, ymin = -Inf, ymax = Inf),
            inherit.aes = FALSE, fill = "grey90", colour = NA) +
  geom_density(alpha = 0.25, linewidth = 0.6) +
  facet_wrap(~parameter, scales = "free", nrow = 1) +
  scale_colour_manual(values = prior_cols) +
  scale_fill_manual(values = prior_cols) +
  labs(x = NULL, y = "prior density", colour = NULL, fill = NULL) +
  theme_classic() +
  theme(legend.position = "top")


#   Response-scaled parameters -----------------------------------------------

#> fig-family-priors -- draws a figure on the page; the page shows the figure and not this code.
count_data <- nec_data |>
  mutate(y = abs(round(y * 100 + rnorm(nrow(nec_data), 0, 15))) |> as.integer())
binom_data <- read.csv("example_binomial.csv")

f_binom <- bayesnecformula(suc | trials(tot) ~ crf(raw_x, model = "nec4param"))

by_family <- bind_rows(
  prior_draws(get_priors(f_gauss, data = nec_data,   family = gaussian()), "gaussian"),
  prior_draws(get_priors(f_gauss, data = count_data, family = poisson()),  "poisson"),
  prior_draws(get_priors(f_binom, data = binom_data, family = binomial()), "binomial")) |>
  filter(parameter %in% c("top", "bot")) |>
  mutate(family = factor(set, c("gaussian", "poisson", "binomial")),
         parameter = factor(parameter, c("top", "bot")))

ggplot(by_family, aes(value, colour = parameter, fill = parameter)) +
  geom_density(alpha = 0.3, linewidth = 0.6) +
  facet_wrap(~family, scales = "free", nrow = 1) +
  scale_colour_manual(values = c(top = "#1b6ca8", bot = "#c1440e")) +
  scale_fill_manual(values = c(top = "#1b6ca8", bot = "#c1440e")) +
  labs(x = NULL, y = "prior density", colour = NULL, fill = NULL) +
  theme_classic() +
  theme(legend.position = "top")


#   Predictor-scaled parameters ----------------------------------------------

#> fig-nec-prior -- draws a figure on the page; the page shows the figure and not this code.
nec_prior <- get_priors(f_binom, data = binom_data, family = binomial())
pars <- as.numeric(strsplit(
  gsub("lognormal\\(|\\)", "", nec_prior$prior[nec_prior$nlpar == "nec"]),
  ", ")[[1]])
concs <- sort(unique(binom_data$raw_x))

# The axis is logarithmic, so the density is taken with respect to log(x);
# plotting dlnorm() against a log axis would distort the shape into a decay.
grid <- data.frame(x = exp(seq(log(min(concs)) - 2, log(max(concs)) + 4,
                               length.out = 600)))
grid$d <- dnorm(log(grid$x), pars[1], pars[2])

ggplot(grid, aes(x, d)) +
  geom_area(data = subset(grid, x >= min(concs) & x <= max(concs)),
            fill = "#1b6ca8", alpha = 0.25) +
  geom_line(colour = "#1b6ca8", linewidth = 0.7) +
  geom_vline(xintercept = range(concs), linetype = 2, colour = "grey40") +
  geom_rug(data = data.frame(x = concs), aes(x = x), inherit.aes = FALSE,
           length = unit(0.09, "npc"), linewidth = 0.8, colour = "#c1440e") +
  scale_x_log10() +
  labs(x = "concentration", y = "prior density") +
  theme_classic()


